test('optional facilitation matches every proposal before and during activity',async()=>{
 const {stages}=await import('../dist/logic.mjs');const {extraActivities}=await import('../dist/activities.mjs');const {getFacilitation}=await import('../dist/facilitation.mjs');
 for(const s of stages){for(const a of ['original',...(extraActivities[s.id]?['extra']:[])]){
  const f=await fixture();f.click(`[data-stage="${s.id}"]`);if(a==='extra')f.click('[data-activity="extra"]');else if(s.id==='5y')f.click('[data-activity="original"]');
  const expected=getFacilitation(s.id,a);
  assert.equal(f.d.querySelectorAll('details.facilitation').length,1);assert.equal(f.d.querySelector('.facilitation').open,false);
  assert.equal(f.d.querySelectorAll('.facilitation summary').length,1);assert.equal(f.d.querySelectorAll('.facilitation dt').length,4);
  assert.ok(f.text('.facilitation').includes(expected.model));f.click('.facilitation summary');assert.equal(f.d.querySelector('.facilitation').open,true);
  assert.ok(f.d.querySelector('#start-session'));assert.equal(f.d.querySelector('#exercise'),null);
  f.click('#start-session');assert.ok(f.text('.facilitation').includes(expected.support));
  f.click('.facilitation summary');f.click('#pause-session');assert.equal(f.d.querySelector('.facilitation'),null);
  f.click('#resume-session');assert.ok(f.text('.facilitation').includes(expected.observe));
  f.click('#finish-session');assert.equal(f.d.querySelector('.facilitation'),null);assert.match(f.text('#activity'),/Por hoy está bien/);
 }}
});
