test('answer-specific feedback survives pause and changes correctly when the choice is revised',async()=>{
 const {extraActivities}=await import('../dist/activities.mjs');
 for(const stage of ['3y','5y','7y','12y']){
  const f=await fixture();f.click(`[data-stage="${stage}"]`);f.click('[data-activity="extra"]');f.click('#start-session');
  for(const [step,q]of extraActivities[stage].steps.entries()){
   for(const [choice]of q.options.filter(([id])=>id!==q.answer)){
    f.click(`[data-extra-answer="${choice}"]`);assert.equal(f.text('#feedback'),'');f.click('#check-extra');assert.equal(f.text('#feedback'),q.feedback[choice]);
    assert.equal(f.d.querySelector('#natural-close').hidden,true);f.click('#pause-session');f.click('#resume-session');assert.equal(f.text('#feedback'),q.feedback[choice]);
    assert.equal(f.d.querySelector(`[data-extra-answer="${choice}"]`).getAttribute('aria-pressed'),'true');
   }
   f.click(`[data-extra-answer="${q.answer}"]`);f.click('#check-extra');assert.equal(f.text('#feedback'),q.explanation);assert.equal(f.d.querySelector('#natural-close').hidden,false);if(step===0)f.click('#next-extra');
  }
  assert.ok(f.dom.window.localStorage.length<=1);assert.equal(f.dom.window.sessionStorage.length,0);
 }
});

