test('Dani branches, backtracking and all twelve endings leave no story choices in storage',async()=>{const {storyBranches,storyClosings}=await import('../dist/reflection.mjs');for(const [branch,b] of Object.entries(storyBranches))for(const action of b.options)for(const ending of storyClosings){const f=await fixture();f.click('[data-route="5y:reflection"]');f.click('#start-session');const key='education-facilitation-guide:progress',before=f.dom.window.localStorage.getItem(key);f.click('[data-perspective="unknown"]');f.click('#reflection-continue');f.click(`[data-story-branch="${branch}"]`);assert.match(f.text('.story-consequence'),new RegExp(b.scene.slice(0,15)));f.click(`[data-story-action="${action.id}"]`);f.click(`[data-story-closing="${ending.id}"]`);assert.ok(f.text('#story-ending').includes(action.result));assert.ok(f.text('#story-ending').includes(ending.text));assert.equal(f.dom.window.localStorage.getItem(key),before);f.click('#story-back');assert.equal(f.d.querySelectorAll('[data-story-closing]').length,2);f.click('#story-back');assert.equal(f.d.querySelectorAll('[data-story-action]').length,2);f.click('#story-back');assert.equal(f.d.querySelectorAll('[data-story-branch]').length,3);f.click('#reflection-pass');assert.match(f.text('#activity'),/Por hoy está bien/);}});
