test('companion Escape closes from launcher and all internal controls, returning focus',async()=>{
 const f=await fixture();f.click('[data-stage="5y"]');f.click('[data-activity="extra"]');f.click('#start-session');
 const dock=f.d.querySelector('#activity-companion'),summary=dock.querySelector('summary');
 for(const selector of ['summary','#companion-hint','#companion-gesture','#companion-hide','#companion-edit','#companion-close']){
  dock.open=true;const target=dock.querySelector(selector);target.focus();target.dispatchEvent(new f.dom.window.KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true}));assert.equal(dock.open,false);assert.equal(f.d.activeElement,summary);
 }
 dock.open=true;f.click('#companion-edit');const select=f.d.querySelector('#companion-shape');select.focus();select.dispatchEvent(new f.dom.window.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));assert.equal(dock.open,false);assert.equal(f.d.activeElement,summary);
});
test('companion return action is hidden outside an active activity and restored on resume',async()=>{
 const f=await fixture();assert.equal(f.d.querySelector('#companion-close').hidden,true);f.click('[data-stage="5y"]');f.click('[data-activity="extra"]');f.click('#start-session');assert.equal(f.d.querySelector('#companion-close').hidden,false);
 f.click('#pause-session');assert.equal(f.d.querySelector('#companion-close').hidden,true);assert.equal(f.d.querySelector('#activity-companion'),null);
 f.click('#resume-session');assert.equal(f.d.querySelector('#companion-close').hidden,false);f.click('#finish-session');assert.equal(f.d.querySelector('#companion-close').hidden,true);f.click('#restart-session');assert.equal(f.d.querySelector('#companion-close').hidden,true);
});

