async function speechFixture(){const dom=new JSDOM('<main><div id="audio-root"></div></main>',{url:'https://speech-test.invalid/',pretendToBeVisual:true}),w=dom.window,spoken=[];let failing=false,attempts=0;const synthesis={speaking:false,pending:false,getVoices:()=>[{lang:'en-US',localService:true}],speak(u){spoken.push(u);},cancel(){attempts++;if(failing)throw Error('mock cancel failure');}};Object.defineProperty(w,'speechSynthesis',{value:synthesis});Object.defineProperty(w,'SpeechSynthesisUtterance',{value:class{constructor(text){this.text=text;}}});const api=await import('../dist/language-audio.mjs'),root=w.document.querySelector('#audio-root');api.mountLanguageAudio(root,'language-en',[0]);return {dom,w,root,api,spoken,setFailure(v){failing=v;},get attempts(){return attempts;}};}
test('speech cancellation failure remains visible after leaving or replacing the language panel',async()=>{const f=await speechFixture();f.root.querySelector('[data-speech-word]').click();assert.equal(f.spoken.length,1);f.setFailure(true);f.api.stopLanguageAudio(f.w.document);f.root.innerHTML='<p>Otra actividad</p>';let warning=f.w.document.querySelector('#speech-stop-warning');assert.ok(warning?.isConnected);assert.equal(warning.getAttribute('role'),'alert');assert.match(warning.textContent,/No se pudo confirmar.*Cierra esta página/);const attempts=f.attempts;f.api.stopLanguageAudio(f.w.document);assert.equal(f.attempts,attempts+1);assert.ok(f.w.document.querySelector('#speech-stop-warning'));f.api.mountLanguageAudio(f.root,'language-en',[1]);assert.match(f.root.querySelector('#speech-error').textContent,/No se pudo confirmar/);f.setFailure(false);f.api.stopLanguageAudio(f.w.document);assert.equal(f.w.document.querySelector('#speech-stop-warning'),null);f.dom.window.close();});
test('failed Repeat exposes the cancellation warning and sends no additional utterance',async()=>{const f=await speechFixture();f.root.querySelector('[data-speech-word]').click();f.setFailure(true);f.root.querySelector('#speech-repeat').click();assert.equal(f.spoken.length,1);assert.match(f.root.querySelector('#speech-error').textContent,/No se pudo confirmar/);f.setFailure(false);f.api.stopLanguageAudio(f.w.document);f.dom.window.close();});

